'use strict';
function main(){
var m=6.8, v=840.5;
var E=0.5*m*v*v;
var levels=[["IIA",300],["II",430],["IIIA",600],["III",3400],["IV",3600]];
var need="beyond IV";for(var i=0;i<levels.length;i++){if(E<=levels[i][1]){need=levels[i][0];break;}}
return {bullet_mass_g:m*1000, velocity_ms:v, kinetic_energy_j:Math.round(E), nij_level_to_stop:need};
}
try{var out=main();console.log(JSON.stringify(out));}catch(e){console.log(JSON.stringify({error:String(e&&e.message||e)}));process.exitCode=1;}

